import{_ as s}from"./chunks/Audio.COine8Wh.js";import{c as o,o as t,j as e,G as n,ae as r,a}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"REINSTATING COMMON SENSE SCHOOL DISCIPLINE POLICIES","description":"","frontmatter":{"legisId":"2025-04-23-reinstating-common-sense-school-discipline-policies","title":"REINSTATING COMMON SENSE SCHOOL DISCIPLINE POLICIES","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/reinstating-common-sense-school-discipline-policies/","publishDate":"2025-04-23T18:57:17-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-23-reinstating-common-sense-school-discipline-policies.md","filePath":"executive-orders/2025-04-23-reinstating-common-sense-school-discipline-policies.md"}'),l={name:"executive-orders/2025-04-23-reinstating-common-sense-school-discipline-policies.md"},g=Object.assign(l,{setup(c){return(d,i)=>(t(),o("div",null,[i[0]||(i[0]=e("h1",{id:"reinstating-common-sense-school-discipline-policies",tabindex:"-1"},[a("REINSTATING COMMON SENSE SCHOOL DISCIPLINE POLICIES "),e("a",{class:"header-anchor",href:"#reinstating-common-sense-school-discipline-policies","aria-label":'Permalink to "REINSTATING COMMON SENSE SCHOOL DISCIPLINE POLICIES"'},"​")],-1)),n(s),i[1]||(i[1]=r('<p>Published on Wednesday, April 23, 2025</p><ul><li>The Federal Government will no longer tolerate risks to children&#39;s safety in classrooms from school discipline based on discriminatory “equity” ideology.</li><li>The 2014 &quot;Dear Colleague&quot; letter, which prompted schools to adopt race-based discipline practices, is criticized for making schools less safe.</li><li>A 2018 report noted that schools avoided disciplining misconduct to prevent racial disparity in discipline statistics, leading to increased classroom disorder.</li><li>Disciplinary decisions should focus on individual student behavior, not racial statistics, as concluded by the Federal Commission on School Safety.</li><li>The 2014 letter was rescinded, but 2023 guidance reintroduced race-based disciplinary practices, causing more classroom disorder.</li></ul><p><strong>Actions Ordered:</strong></p><ul><li><strong>30 Days</strong>: Secretary of Education to issue new guidance on school discipline to prevent racial discrimination under Title VI.</li><li><strong>Immediate Action</strong>: Secretary of Education to act against institutions not complying with Title VI protections.</li><li><strong>60 Days</strong>: Coordination with Governors and State Attorneys General on preventing racial discrimination in school discipline.</li><li><strong>90 Days</strong>: Secretary of Defense to issue a revised discipline code for military-service families.</li><li><strong>120 Days</strong>: Secretary of Education to submit a report including: <ul><li>Analysis of past Title VI investigations.</li><li>Assessment of non-profits promoting discriminatory discipline and recommendations.</li><li>Evaluation of alternative discipline policies.</li><li>Model policies promoting safety and American values, free from discrimination.</li></ul></li></ul><p><strong>Notes:</strong></p><ul><li>The order does not limit the authority of executive departments or agencies.</li><li>Implementation is subject to applicable law and funding availability.</li><li>The order does not create enforceable rights against the U.S. or its entities.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/reinstating-common-sense-school-discipline-policies/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/reinstating-common-sense-school-discipline-policies/</a></p>',7))]))}});export{u as __pageData,g as default};
